// All backend calls of the Suppliers page. Docs: ../backend/doc/week1/supplier.txt
import api from "../../services/api";
import { optionalField } from "../../utils/body";
import { toMoneyNumber } from "../../utils/money";

// Only the documented fields. `code` is generated by the server and never sent.
function toSupplierBody(form, isEdit) {
  return {
    name: form.name.trim(),
    // Optional text: left out on create when empty; null on edit when emptied (null clears it).
    contactPerson: optionalField(form.contactPerson, isEdit),
    phone: optionalField(form.phone, isEdit),
    email: optionalField(form.email, isEdit),
    taxNumber: optionalField(form.taxNumber, isEdit),
    // Money: sent as a number, never null (an empty field = 0). May be negative.
    openingBalance: toMoneyNumber(form.openingBalance),
  };
}

export async function getSuppliers() {
  const response = await api.get("/supplier");
  return response.data.data;
}

export async function createSupplier(form) {
  const response = await api.post("/supplier", toSupplierBody(form, false));
  return response.data.data;
}

export async function updateSupplier(id, form) {
  const response = await api.patch(`/supplier/${id}`, toSupplierBody(form, true));
  return response.data.data;
}

export async function deleteSupplier(id) {
  await api.delete(`/supplier/${id}`);
}
